; ============================================================ heap ====
; No storage is emitted - a .COM owns everything past its image, so
; these are addresses and NASM does the arithmetic.

_hstack:        equ     310        ; 54 worst-case + 256 interrupt reserve
_htop:          equ     0FFFEh - _hstack

_hsize:         dw      _htop - _heap        ; NASM computes this
        align   2                           ; keep the u16 view aligned
_heap:
_heapw:         equ     _heap        ; same bytes, u16 view

; =========================================================== views ====
; No storage: each is a name for an offset into something else.

modir__listNames: equ     _heap        ; u8[3328]
modir__listDir: equ     _heap + 3328        ; u8[256]
piece:          equ     _heap + 3584        ; u8[4096]
clip:           equ     _heap + 7680        ; u8[8192]
